-- Isle of Ashes story chain: authored handlers for the remade map, appended by story.py after the generated data
-- (Isle.*) and the compiled dialogue callbacks. Every step names the MM9 script and lines it reproduces; what the
-- engine cannot show yet (cameras, fades, the sinking islet, the sailing boat) is logged as [MM9Unsupported] once.

local FACE_INVISIBLE = 0x00002000
local FACE_UNTOUCHABLE = 0x20000000
local ACTOR_INVISIBLE = 0x00010000
local TICK_SECONDS = 0.25               -- real seconds per story tick (the timer interval is in game seconds: x 30)
local AIBASE_RADIUS = 500 * 2.56        -- IsleAshesBook.scr:86 GetObjects AIBase, 500
local EFFECT_SCALE = 2.56               -- MM9 effects at the world scale
local MINUTES_PER_DAY = 24 * 60

local EVENT_TIMER = 31000
local EVENT_LOAD = 31001
local EVENT_LEAVE = 31002
local EVENT_KILLED = 31003

local function hasKey(rawKey)
    return MM9.hasKey(rawKey) == 1
end

local function unsupported(what)
    local name = "Isle.Unsupported." .. what
    if evt.GetMapVar(name, 0) == 0 then
        evt.SetMapVar(name, 1)
        evt.Debug("[MM9Unsupported] isleofashes: " .. what)
    end
end

local function showActor(name, shown)
    local actor = Isle.actorByName[name]
    if actor ~= nil then
        evt.SetMonsterBit(actor, ACTOR_INVISIBLE, shown and 0 or 1)
    end
end

local function removeFaces(name)
    evt.SetFacetBitOutdoors(Isle.cogs[name], FACE_INVISIBLE, 1)
    evt.SetFacetBitOutdoors(Isle.cogs[name], FACE_UNTOUCHABLE, 1)
end

local function scriptParam(objectName, index)
    local entry = Isle.scriptObjects[objectName]
    return entry ~= nil and entry.params[index + 1] or nil
end

-- Ticks: the story timer counts them; delayed steps wait for a tick (MM9 'wait <slot> <seconds> <routine>').
local pending = {}

local function ticks()
    return evt.GetMapVar("Isle.Ticks", 0)
end

local function after(seconds, step)
    table.insert(pending, { at = ticks() + math.max(1, math.floor(seconds / TICK_SECONDS + 0.5)), step = step })
end

-- Messages between DAT objects (Trigger TargetName/MessageName, DeathTriggerTarget, 'trigger <object> <message>').
local handlers = {}
local send

local function on(target, message, handler)
    handlers[target] = handlers[target] or {}
    handlers[target][string.lower(message)] = handler
end

send = function(target, message, sender)
    local byTarget = handlers[target]
    local handler = byTarget ~= nil and byTarget[string.lower(message)] or nil
    if handler == nil then
        evt.Debug("[MM9RuntimeError] kind=trigger_message map=isleofashes target=" .. tostring(target)
            .. " message=" .. tostring(message) .. " sender=" .. tostring(sender))
        return
    end
    handler(sender)
end

-- tm_Hardrock.scr:29-54 (KillControl, ScriptParams "8 27 200"): each OneDown counts; at the 8th the key, the quest
-- sound and the experience. The 12 flyers whose DeathTriggerTarget is KillControl send it (Isle.deathTriggers).
on("KillControl", "OneDown", function()
    local pieces = tonumber(scriptParam("KillControl", 0))
    local count = MM9.scrValue(Isle.scriptObjects.KillControl.source, "count", 0) + 1
    MM9.setScrValue(Isle.scriptObjects.KillControl.source, "count", count)
    if count == pieces then
        MM9.giveKey(tonumber(scriptParam("KillControl", 1)))
        MM9.playSound("sounds\\events\\quest.wav")
        local experience = tonumber(scriptParam("KillControl", 2)) or 0
        if experience ~= 0 then
            MM9.giveExperience(experience)
        end
    end
end)

-- AutoResurrect.scr:66-87 hides the bunker's Bone Thrashers under the ground; :34-46 they rise on RESURRECT
-- (Trigger2 in front of the bunker doors sends it to BoneThrasher1-3, then 'off' to itself).
for _, trigger in ipairs(Isle.triggers) do
    for _, pair in ipairs(trigger.messages) do
        local target, message = pair[1], pair[2]
        if string.lower(message) == "resurrect" and Isle.actorByName[target] ~= nil then
            on(target, message, function() showActor(target, true) end)
        elseif string.lower(message) == "off" and target == trigger.name then
            on(target, message, function() evt.SetMapVar("Isle.TriggerOff." .. trigger.name, 1) end)
        end
    end
end

-- Isle_Summoner.scr:59-69 (LichSummoner, "Skeletoid SpawnLocation"): each 'spawn' summons a Skeletoid at
-- SpawnLocation; after the fifth the trigger is removed (the sixth still spawns, as the script counts before).
on("LichSummoner", "spawn", function()
    if evt.GetMapVar("Isle.LichGone", 0) == 1 then
        return
    end
    local counter = evt.GetMapVar("Isle.SummonCount", 0)
    if counter > 5 then
        return
    end
    evt.SetMapVar("Isle.SummonCount", counter + 1)
    local location = Isle.points[scriptParam("LichSummoner", 1)]
    evt.SummonMonstersById({ monster = Isle.monsterIds[scriptParam("LichSummoner", 0)], x = location.x,
        y = location.y, z = location.z, radius = 128, count = 1 })
end)

-- TriggerEffects message 10: the Lich is destroyed with the islet.
on("LichSummoner", "destroy", function()
    evt.SetMapVar("Isle.LichGone", 1)
    showActor("LichSummoner", false)
end)

-- Isle_IslandExplosion.scr:28-52: five bursts of elemental blast and black smoke, 1-2 s apart, then mist.
local function explode(name, burst)
    local point = Isle.points[name]
    if burst < 5 then
        evt.SpawnWorldEffect("mm9:elemental_blast", point.x, point.y, point.z, EFFECT_SCALE)
        evt.SpawnWorldEffect("mm9:blacksmoke", point.x, point.y, point.z, EFFECT_SCALE)
        after(evt.RandomBetween(4, 8) * TICK_SECONDS, function() explode(name, burst + 1) end)
    else
        evt.SpawnWorldEffect("mm9:mist", point.x, point.y, point.z, EFFECT_SCALE)
    end
end

for index = 0, 4 do
    local name = "ExplosionEffect" .. index
    on(name, "explode", function() explode(name, 0) end)
end

-- A Trigger object fires: its messages in order (TargetName1..10).
local function fireTrigger(trigger)
    for _, pair in ipairs(trigger.messages) do
        send(pair[1], pair[2], trigger.name)
    end
end

local function triggerNamed(name)
    for _, trigger in ipairs(Isle.triggers) do
        if trigger.name == name then
            return trigger
        end
    end
    return nil
end

on("TriggerEffects", "trigger", function(sender) fireTrigger(triggerNamed("TriggerEffects")) end)

-- DestructableBrush 'destroy' (TriggerDestroyOnly): the brush goes; FortWall0's DeathTriggerTarget is TriggerEffects.
on("FortWall", "destroy", function() removeFaces("FortWall") end)
on("FortWall0", "destroy", function()
    if evt.GetMapVar("Isle.FortWall0Destroyed", 0) == 1 then
        return
    end
    evt.SetMapVar("Isle.FortWall0Destroyed", 1)
    removeFaces("FortWall0")
    send("TriggerEffects", "trigger", "FortWall0")
end)

-- Shooter objects (ShootInterval 0: one FireBolt per 'on'): Shooter fires out of the bunker through the broken
-- FortWall (its own aim), Shooter0 at the islet's FortWall0 (500 damage).
local function fireShooter(name, damage, target)
    local from = Isle.points[name]
    local to = target or { x = from.x + from.dirX * 4000, y = from.y + from.dirY * 4000, z = from.z + from.dirZ * 4000 }
    evt.FireMissile("Fire", from.x, from.y, from.z, to.x, to.y, to.z, damage, "Fire", 0)
end

on("Shooter", "on", function() fireShooter("Shooter", 5, nil) end)
on("Shooter0", "on", function() fireShooter("Shooter0", 500, Isle.points.FortWall0) end)

-- IS_Boat.scr:34-44: the boat shows and sails to BoatMarker's x.
on("Boat", "move", function()
    evt.SetSprite(Isle.cogs.Boat, 1)
    unsupported("Boat move: decorations cannot move; the boat shows at its berth")
end)

-- IA_Island.scr / Door Terrain3: the islet sinks 1000 down (20 s).
on("Terrain3", "open", function() unsupported("Terrain3 open: the islet is part of the height map and cannot sink") end)

for _, camera in ipairs({ "Camera0", "Camera1", "Camera2", "Camera3" }) do
    on(camera, "on", function() unsupported("cinema cameras (" .. camera .. ")") end)
    on(camera, "off", function() end)
end
on("Camera2", "Pan", function() unsupported("cinema camera pan (IA_Camera2.scr)") end)

-- ExitTrigger 'trigger': the exit runs without its volume (ExitTrigger1 lies 43 000 west, out at sea): the travel
-- days pass, then the party arrives at the destination's start point (map_transitions.txt row of the exit).
local function takeExit(name)
    local exit = Isle.exits[name]
    if exit.travelDays > 0 then
        evt.AdvanceGameMinutes(exit.travelDays * MINUTES_PER_DAY)
    end
    evt.MoveToMap(exit.x, exit.y, exit.z, exit.yawUnits, 0, 0, 0, 0, exit.map)
end

on("ExitTrigger1", "trigger", function() takeExit("ExitTrigger1") end)

-- IsleAshesBook.scr: the cinema. Each entry: seconds after the use, source lines, the step.
local cinema = {
    -- :OnUse 44-50: DestroyMonsters (81-103: AIBase within 500 of the book are removed), fade out, letterbox,
    -- camera0 on, fade in; wait 1 StartDestroy.
    { 0.0, function()
        local book = Isle.points.Book
        for name, actor in pairs(Isle.actorByName) do
            local x, y, z = evt.GetMapActorPosition(actor)
            if x ~= nil and (x - book.x) ^ 2 + (y - book.y) ^ 2 + (z - book.z) ^ 2 <= AIBASE_RADIUS ^ 2 then
                showActor(name, false)
            end
        end
        unsupported("cinema fades and letterbox (ScreenFadeout, Letterbox)")
        send("Camera0", "on", "Book")
    end },
    -- :StartDestroy 106-115: SpawnMgr off (no SpawnMgr on the isle), FortWall destroy; wait .2 Shoot.
    { 1.0, function() send("FortWall", "destroy", "Book") end },
    -- :Shoot 119-125: Shooter on; wait 1 Camera1.
    { 1.2, function() send("Shooter", "on", "Book") end },
    -- :Camera1 128-136.
    { 2.2, function() send("Camera1", "on", "Book") end },
    -- :Shoot2 139-146: Shooter0 on, ebolt01; wait 1 Camera2; wait 1.3 OnSink.
    { 3.2, function()
        send("Shooter0", "on", "Book")
        MM9.playSound("sounds\\spells\\ebolt01.wav")
    end },
    -- :Camera2 149-157.
    { 4.2, function() send("Camera2", "on", "Book") end },
    -- :OnSink 160-186: eblast03 and drown01, FortWall0 destroy (its death triggers TriggerEffects: the five
    -- explosions and the Lich's end), the burning loop, Terrain3 open, Boat move, key 28, 5200 experience, quest.
    { 4.5, function()
        MM9.playSound("sounds\\spells\\eblast03.wav")
        MM9.playSound("sounds\\events\\drown01.wav")
        send("FortWall0", "destroy", "Book")
        MM9.playSound("sounds\\ambient\\fire\\forrestfireloop.wav")
        send("Terrain3", "open", "Book")
        send("Boat", "move", "Book")
        MM9.giveKey(28)
        MM9.giveExperience(5200)
        MM9.playSound("sounds\\events\\quest.wav")
    end },
    -- :OnCrane 190-196: camera2 Pan; IA_Camera2.scr:30-49 turns to the boat and, 3.5 s later, sends the book Crane.
    { 8.5, function() send("Camera2", "Pan", "Book") end },
    -- :OnCrane2 199-208: drown01, camera3; wait 4 FadeOut.
    { 12.0, function()
        MM9.playSound("sounds\\events\\drown01.wav")
        send("Camera3", "on", "Book")
    end },
    -- :FadeOut 211-215 and :FadeOut2 218-226: letterbox off, camera3 off, ExitTrigger1 trigger (Sturmford).
    { 17.0, function() send("ExitTrigger1", "trigger", "Book") end },
}

local function runCinema()
    local started = evt.GetMapVar("Isle.CinemaStart", -1)
    if started < 0 then
        return
    end
    local done = evt.GetMapVar("Isle.CinemaDone", 0)
    local elapsed = (ticks() - started) * TICK_SECONDS
    while done < #cinema and cinema[done + 1][1] <= elapsed do
        done = done + 1
        evt.SetMapVar("Isle.CinemaDone", done)
        cinema[done][2]()
    end
    if done >= #cinema then
        evt.SetMapVar("Isle.CinemaStart", -1)
    end
end

-- IsleAshesBook.scr:29-54 OnUse: ContainerCheck (58-77: the party stands on the bunker's AI rails; any party at the
-- book does here), then the cinema once Forad has joined (key 29) and before it ran (key 28).
on("Book", "Use", function()
    if evt.GetMapVar("Isle.CinemaStart", -1) >= 0 then
        return
    end
    if hasKey(29) and not hasKey(28) then
        evt.SetMapVar("Isle.CinemaStart", ticks())
        evt.SetMapVar("Isle.CinemaDone", 0)
        runCinema()
    end
end)

RegisterEvent(Isle.events.Book, "Book", function() send("Book", "Use", "player") end, "Read")
-- PropTrigger.scr:24-36 (Prop159, "Book Use"): using the lectern uses the book.
RegisterEvent(Isle.events.Prop159, "Lectern", function() send("Book", "Use", "Prop159") end, "Read")

-- DoorLock.scr:22-48 (BunkerDoor1/2, ScriptParams "568 1"): with the Turret Key (item 568) the door unlocks and the
-- key is taken (p1 = 1); the doors are Sticky (they stay open) and DoubleDoorName opens the pair together. Without
-- the key the doors stay Locked. The mechanisms (the old scene's MM9 pivots) carry the door sounds.
local MECHANISM_OPEN = 0
local MECHANISM_TOGGLE = 2

local function useBunkerDoor()
    if evt.GetMapVar("Isle.BunkerOpen", 0) == 1 then
        return
    end
    if MM9.hasItem(568, "DOORLOCK.scr:25") ~= 1 then
        evt.StatusText("Locked")
        return
    end
    MM9.takeItem(568, "DOORLOCK.scr:34")
    evt.SetMapVar("Isle.BunkerOpen", 1)
    evt.SetOutdoorModelMechanismState(Isle.mechanisms.BunkerDoor1, MECHANISM_OPEN)
    evt.SetOutdoorModelMechanismState(Isle.mechanisms.BunkerDoor2, MECHANISM_OPEN)
end

RegisterEvent(Isle.events.BunkerDoor1, "BunkerDoor1", useBunkerDoor, "Open")
RegisterEvent(Isle.events.BunkerDoor2, "BunkerDoor2", useBunkerDoor, "Open")
SetMapContextAction(Isle.events.BunkerDoor1, { kind = "open_door", source = "mm9_mechanism", targetName = "BunkerDoor1" })
SetMapContextAction(Isle.events.BunkerDoor2, { kind = "open_door", source = "mm9_mechanism", targetName = "BunkerDoor2" })

-- RotatingDoor8 (Yrsa's hut door, no script, not locked): use opens or closes it. MM9 closes it again after
-- CloseWaitTime 5 s; here it stays as the party leaves it.
RegisterEvent(Isle.events.RotatingDoor8, "RotatingDoor8", function()
    evt.SetOutdoorModelMechanismState(Isle.mechanisms.RotatingDoor8, MECHANISM_TOGGLE)
end, "Open")
SetMapContextAction(Isle.events.RotatingDoor8, { kind = "open_door", source = "mm9_mechanism",
    targetName = "RotatingDoor8" })

-- DAT triggers the party walks into (PlayerTriggerable; Dims are half extents), each ActivationCount times.
local function updateTriggers()
    local x, y, z = evt.GetPartyPosition()
    for _, trigger in ipairs(Isle.triggers) do
        local countName = "Isle.TriggerCount." .. trigger.name
        local count = evt.GetMapVar(countName, 0)
        if trigger.playerTriggerable and evt.GetMapVar("Isle.TriggerOff." .. trigger.name, 0) == 0
            and (trigger.activations == 0 or count < trigger.activations)
            and math.abs(x - trigger.x) <= trigger.halfX and math.abs(y - trigger.y) <= trigger.halfY
            and math.abs(z - trigger.z) <= trigger.halfZ + 192 then
            evt.SetMapVar(countName, count + 1)
            fireTrigger(trigger)
        end
    end
end

-- FORADWORLD.scr:129-130: shops and passage close at 20:00 (key 5017) and open at 6:00.
local function crossed(previous, current, minute)
    if current >= previous then
        return previous < minute and minute <= current
    end
    return previous < minute or minute <= current
end

local function updateShopHours()
    local minute = evt.CurrentGameMinutes() % MINUTES_PER_DAY
    local previous = evt.GetMapVar("Isle.ForadWorldMinute", -1)
    if previous >= 0 and previous ~= minute then
        if crossed(previous, minute, 20 * 60) then
            MM9.giveKey(5017)
        end
        if crossed(previous, minute, 6 * 60) then
            MM9.takeKey(5017)
        end
    end
    evt.SetMapVar("Isle.ForadWorldMinute", minute)
end

RegisterMapTimerEvent(EVENT_TIMER, TICK_SECONDS * 30, function()
    evt.SetMapVar("Isle.Ticks", ticks() + 1)
    local now = ticks()
    local due = {}
    for index = #pending, 1, -1 do
        if pending[index].at <= now then
            table.insert(due, 1, pending[index].step)
            table.remove(pending, index)
        end
    end
    for _, step in ipairs(due) do
        step()
    end
    runCinema()
    updateTriggers()
    updateShopHours()
end, "Isle of Ashes story")

-- The death of an actor whose DAT object names a DeathTriggerTarget sends its message (KillControl's flyers).
RegisterMonsterKilledHook(EVENT_KILLED, "Isle of Ashes death triggers", function(context)
    local trigger = Isle.deathTriggers[context.actorIndex]
    if trigger ~= nil then
        send(trigger.target, trigger.message, trigger.name)
    end
end)

-- World start.
RegisterMapOnLoadEvent(EVENT_LOAD, "Isle of Ashes presence", function()
    -- FORADWORLD.scr:39-56 Init (ScriptObject0, "isleofashes"): Forad's location key 1024.
    for rawKey = 1024, 1033 do
        MM9.takeKey(rawKey)
    end
    MM9.giveKey(1024)
    -- IS_Boat.scr:46-51, 64: the boat stays hidden until it leaves.
    evt.SetSprite(Isle.cogs.Boat, 0)
    -- FORAD.scr:96-108, 178-183 DeleteCheck: Forad has joined the party (key 29).
    if hasKey(29) then
        showActor("ForadDarre", false)
    end
    -- YRSA.scr:106-118, 138-139 Init: Yrsa is gone once Forad has joined (key 29) when the party comes back. MM9 has
    -- no saves on the isle, so it never reloads the map between Forad joining and Yrsa giving the Turret Key; here a
    -- reload in that window would hide her and lock the bunker for good. She leaves after the cinema (key 28) instead.
    if hasKey(29) and hasKey(28) then
        showActor("Yrsa", false)
    end
    -- HideModel.scr:26-34, 55-70 (ShopkeeperHuman2MaleA0, "28 unhide"): Annud Redeye is there after the cinema.
    showActor("ShopkeeperHuman2MaleA0", hasKey(28))
    -- AutoResurrect.scr:66-80: the Bone Thrashers wait under the ground until Trigger2 has fired.
    for _, trigger in ipairs(Isle.triggers) do
        if evt.GetMapVar("Isle.TriggerCount." .. trigger.name, 0) == 0 then
            for _, pair in ipairs(trigger.messages) do
                if string.lower(pair[2]) == "resurrect" then
                    showActor(pair[1], false)
                end
            end
        end
    end
    -- IsleAshesBook.scr:230-243 Init: after the cinema (key 28) FortWall0 is gone and the islet sunk; the Lich went
    -- with it (FortWall0 is ShouldMiniSave, so its death trigger does not fire again).
    if hasKey(28) then
        removeFaces("FortWall0")
        evt.SetMapVar("Isle.FortWall0Destroyed", 1)
        evt.SetMapVar("Isle.LichGone", 1)
        showActor("LichSummoner", false)
    end
end)

-- FORADWORLD.scr:23-36, 135 OnWorldSwitch TakeKey.
RegisterMapOnLeaveEvent(EVENT_LEAVE, "Isle of Ashes location keys", function()
    for rawKey = 1024, 1033 do
        MM9.takeKey(rawKey)
    end
end)
